window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(mod){if(['z','y','c','v','d','a'].includes(key))e.preventDefault();if(key==='z'){flushTap();cancelAction();e.shiftKey?store.redo():store.undo()}if(key==='y'){flushTap();cancelAction();store.redo()}if(key==='c')copy();if(key==='v')paste();if(key==='d')duplicate();if(key==='a'){selection=store.document.objects.map(o=>o.id);tool='select';renderToolbar();renderContext();renderProperties();requestDraw()}return}if(key==='escape'){cancelAction();selection=[];detail=false;renderProperties();renderContext()}if(key==='enter'&&polygon.length)finishPolygon();if(key==='delete'||key==='backspace'){e.preventDefault();detail&&nodeIndex>=0?deleteNode():remove()}if(key===' '){e.preventDefault();space=true}const shortcuts={p:'pen',e:'eraser',m:'highlighter',v:'select',s:'shapes',h:'hand',t:'text'};if(shortcuts[key])setTool(shortcuts[key]);if(key==='+'||key==='='){e.preventDefault();zoom(1.25)}if(key==='-'){e.preventDefault();zoom(.8)}if(key==='0')$('home').click();const dirs={arrowleft:[-1,0],arrowright:[1,0],arrowup:[0,-1],arrowdown:[0,1]};if(dirs[key]){e.preventDefault();const [x,y]=dirs[key],step=e.shiftKey?10:1;if(selection.length)mutateSelected(o=>{o.position.x+=x*step;o.position.y+=y*step});else{view.x-=x*40;view.y-=y*40;requestDraw(true);scheduleSave()}}});window.addEventListener('keyup',e=>{if(e.key===' ')space=false});window.addEventListener('blur',()=>{space=false;if(action)cancelAction()});window.addEventListener('pagehide',()=>{persist();stopCamera()});document.addEventListener('visibilitychange',()=>{if(document.hidden)persist()});
