if(part==='point'){const input=field(panel,'pointName','text',node.label??'',v=>edit((x,n)=>{n.label=v.trim().slice(0,12)}));input.maxLength=12;const suggestions=suggestNames(o,i,node.label??'');if(suggestions.length){panel.append(el('p',{class:'minor'},t('clockwiseSuggestion')+': '+suggestions.map(s=>s.label).join(', ')),el('button',{class:'primary',onclick:()=>edit(x=>{for(const item of suggestions)if(!x.points[item.index].label)x.points[item.index].label=item.label})},t('applyNames')))}const angle=angleAt(o,i);if(angle){panel.append(el('hr'));check(panel,'showWedge',!!node.angle?.visible,v=>edit((x,n)=>{n.angle={mode:'value',...n.angle,visible:v}}));if(node.angle?.visible){selectControl(panel,'angleDisplay',node.angle.mode??'value',['value','none','x','theta','custom'],v=>edit((x,n)=>n.angle.mode=v));if(node.angle.mode==='custom')field(panel,'angleText','text',node.angle.text??'',v=>edit((x,n)=>n.angle.text=v.slice(0,20)));panel.append(el('p',{class:'minor'},`${t('actualAngle')}: ${Number(angle.degrees.toFixed(2))}°`))}}else panel.append(el('p',{class:'minor'},t('noAngle')))}else{const data=node.edgeLabel??{mode:'none',unit:'cm'};selectControl(panel,'edgeDisplay',data.mode,['none','manual','measured'],v=>edit((x,n)=>n.edgeLabel={...data,mode:v}));if(data.mode==='manual'){field(panel,'edgeValue','text',data.value??'',v=>edit((x,n)=>n.edgeLabel.value=v.slice(0,20)));selectControl(panel,'unit',data.unit??'cm',[['cm','cm'],['','none']],v=>edit((x,n)=>n.edgeLabel.unit=v))}const edge=edges(o)[i];if(edge){const length=distance(edge.a,edge.b)/(o.unitsPerCm??CM);panel.append(el('p',{class:'minor'},`${t('actualLength')}: ${Number(length.toFixed(2))} cm`));const lengthInput=field(panel,'setLength','number',Number(length.toFixed(2)),()=>{},.01,1000);lengthInput.step='any';panel.append(el('button',{class:'primary',onclick:()=>{try{edit(x=>setEdgeLength(x,i,+lengthInput.value))}catch{toast('invalidLength')}}},t('applyLength')),el('p',{class:'minor'},t('lengthWarning')))}}posit