function setupGeometryUI(){const panel=el('aside',{id:'pointEditor',class:'point-editor',hidden:'',role:'region'});$('overlay').parentElement.append(panel);const dialog=el('dialog',{id:'triangleDialog'}),form=el('form',{id:'triangleForm'});form.append(el('h2',{'data-i18n':'accurateTriangle'}),el('p',{'data-i18n':'sasHint'}));for(const [id,key,value]of[['sideA','firstSide',5],['sideB','secondSide',6],['included','includedAngle',70]]){const label=el('label',{class:'triangle-field'});label.append(el('span',{'data-i18n':key}),el('input',{id,type:'number',value,min:.01,max:id==='included'?179.99:1000,step:'any',required:'','data-label':key,'aria-label':t(key),'data-math-mode':id==='included'?'angle':'length','data-math-unit':id==='included'?'°':'cm',oninput:updateTriangleResult}));form.append(label)}form.append(el('output',{id:'triangleResult','aria-live':'polite'}));const actions=el('div',{class:'dialog-actions'});actions.append(el('button',{type:'button',onclick:()=>dialog.close(),'data-i18n':'cancel'}),el('button',{class:'primary','data-i18n':'apply'}));form.append(actions);form.onsubmit=e=>{e.preventDefault();try{const old=store.document.objects.find(o=>o.id===triangleTarget),pos=old?.position??screenToWorld({x:width*.35,y:height*.65},view),{object}=triangleSAS(+$('sideA').value,+$('sideB').value,+$('included').value,pos,old?{strokeColour:old.strokeColour,strokeWidth:old.strokeWidth,fill:old.fill}:styleOptions());if(old){object.id=old.id;store.transact(d=>{const i=d.objects.findIndex(o=>o.id===old.id);if(i>=0&&!d.objects[i].locked)d.objects[i]=object});activateObject(object)}else add(object);dialog.close()}catch{toast('invalidTriangle')}};dialog.append(form);document.body.append(dialog)}
